#rf-root,.hf-root{--x3:#2a3366;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx.tx-iris-out{inset:auto;background:transparent;box-shadow:0 0 0 2400px var(--rf-surface);border-radius:50%;width:2400px;height:2400px;left:calc(50% - 1200px);top:calc(50% - 1200px);animation:tx-iris-out 0.5s cubic-bezier(.76,0,.24,1) 6s both;opacity:0}@keyframes tx-iris-out{from{opacity:1}to{opacity:1;width:0;height:0;left:50%;top:50%}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.acc{color:var(--rf-accent);font-style:normal}.cl-p{display:flex;align-items:center;gap:20px;font-size:44px;font-weight:600}
.cl-v{margin-top:30px;font:600 220px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;letter-spacing:-.06em;color:var(--rf-text);transform-origin:left}
.cl-k{font-size:60px;font-weight:600;color:var(--rf-muted);margin:10px 0 60px}
.ci{display:flex;align-items:center;gap:28px;padding:30px 0;border-top:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent);font-size:46px;font-weight:600;line-height:1.15}
.tg{flex:none;width:150px;text-align:center;font:600 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;padding:16px 0;border-radius:14px}
.tg{background:color-mix(in srgb,var(--rf-text) 8%,transparent);color:var(--rf-muted)}.tg.new{background:var(--rf-accent);color:var(--rf-bg)}

