.n24{counter-reset:n24 var(--n24);animation:n24-c 2.2s cubic-bezier(.16,1,.3,1) 0.55s both}
.n24::after{content:counter(n24,decimal)}
@keyframes n24-c{from{--n24:0}to{--n24:2400}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
